"use client";

import { Button } from "@/components/ui/button";
import { Dialog,DialogContent,DialogHeader,DialogTitle } from "@/components/ui/dialog";
import type { Document } from "@prisma/client";
import { Download,FileText,Loader2,Lock,Maximize2,Minimize2,RotateCcw,ShieldCheck,ZoomIn,ZoomOut } from "lucide-react";
import { useEffect,useState } from "react";

interface DocumentViewerModalProps {
  doc: Document | null;
  isOpen: boolean;
  onClose: () => void;
  isChairman?: boolean;
}

export function DocumentViewerModal({
  doc,
  isOpen,
  onClose,
  isChairman = false,
}: DocumentViewerModalProps) {
  const [isMounted, setIsMounted] = useState(false);
  const [blobUrl, setBlobUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [loadError, setLoadError] = useState<boolean>(false);
  const [isFullScreen, setIsFullScreen] = useState<boolean>(false);
  const [zoomLevel, setZoomLevel] = useState<number>(100);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (!doc || !isOpen) {
      setBlobUrl(null);
      setIsFullScreen(false);
      setZoomLevel(100);
      return;
    }

    let isCancelled = false;
    setLoading(true);
    setLoadError(false);

    fetch(doc.fileUrl, {
      headers: {
        "ngrok-skip-browser-warning": "69420",
      },
    })
      .then((res) => {
        if (!res.ok) throw new Error("Не удалось загрузить файл");
        return res.blob();
      })
      .then((blob) => {
        if (!isCancelled) {
          const url = URL.createObjectURL(blob);
          setBlobUrl(url);
          setLoading(false);

          fetch("/api/documents/read", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ documentId: doc.id }),
          }).catch(() => {});
        }
      })
      .catch(() => {
        if (!isCancelled) {
          setLoadError(true);
          setLoading(false);
        }
      });

    return () => {
      isCancelled = true;
      if (blobUrl) {
        URL.revokeObjectURL(blobUrl);
      }
    };
  }, [doc, isOpen]);

  if (!isMounted || !doc) return null;

  const lowerUrl = doc.fileUrl.toLowerCase();
  const isPdf = lowerUrl.endsWith(".pdf") || doc.fileType?.includes("pdf");
  const isImage = /\.(jpg|jpeg|png|webp)$/i.test(lowerUrl) || doc.fileType?.includes("image");

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        className={`flex flex-col p-0 overflow-hidden rounded-2xl select-none transition-all duration-300 ${
          isFullScreen
            ? "w-screen h-screen max-w-none max-h-none rounded-none border-0 m-0"
            : "w-[95vw] sm:max-w-[90vw] md:max-w-[85vw] lg:max-w-[75vw] xl:max-w-[1200px] h-[90vh] sm:h-[88vh]"
        }`}
      >
        <DialogHeader className="p-3 sm:p-4 border-b flex flex-row items-center justify-between gap-2 bg-card">
          <div className="space-y-0.5 min-w-0 flex-1">
            <div className="flex items-center gap-2 flex-wrap">
              <DialogTitle className="text-sm sm:text-base font-bold truncate">{doc.title}</DialogTitle>
              {doc.category === "PROTOCOL" && (
                <span className="inline-flex items-center gap-1 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[11px] font-semibold text-emerald-600 dark:text-emerald-400">
                  <ShieldCheck size={12} /> Протокол
                </span>
              )}
            </div>
            {doc.description && (
              <p className="text-xs text-muted-foreground truncate">{doc.description}</p>
            )}
          </div>

          <div className="flex items-center gap-1 shrink-0">
            {/* Кнопка Полноэкранного режима */}
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 rounded-lg"
              onClick={() => setIsFullScreen((v) => !v)}
              title={isFullScreen ? "Свернуть" : "На весь экран"}
            >
              {isFullScreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
            </Button>

            {/* Скачивание видно ТОЛЬКО Председателю */}
            {isChairman && (
              <Button variant="outline" size="sm" asChild className="rounded-xl gap-1.5 h-8 text-xs">
                <a href={doc.fileUrl} download target="_blank" rel="noreferrer">
                  <Download size={14} />
                  <span className="hidden sm:inline">Скачать</span>
                </a>
              </Button>
            )}
          </div>
        </DialogHeader>

        {/* Панель масштабирования (только для картинок/фото, у PDF есть своя нативная панель) */}
        {isImage && blobUrl && !loading && !loadError && (
          <div className="flex items-center justify-center gap-2 py-1.5 px-3 bg-muted/60 border-b text-xs">
            <Button
              variant="outline"
              size="icon"
              className="h-7 w-7 rounded-md"
              onClick={() => setZoomLevel((z) => Math.max(50, z - 25))}
              disabled={zoomLevel <= 50}
              title="Уменьшить"
            >
              <ZoomOut size={13} />
            </Button>
            <span className="w-12 text-center font-mono font-medium text-[11px]">{zoomLevel}%</span>
            <Button
              variant="outline"
              size="icon"
              className="h-7 w-7 rounded-md"
              onClick={() => setZoomLevel((z) => Math.min(250, z + 25))}
              disabled={zoomLevel >= 250}
              title="Увеличить"
            >
              <ZoomIn size={13} />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 rounded-md ml-1"
              onClick={() => setZoomLevel(100)}
              title="Сбросить"
            >
              <RotateCcw size={13} />
            </Button>
          </div>
        )}

        {/* Экран встроенного просмотра */}
        <div
          className="flex-1 bg-muted/40 relative overflow-auto flex items-center justify-center p-2 touch-pan-x touch-pan-y"
          onContextMenu={(e) => e.preventDefault()}
        >
          {loading ? (
            <div className="flex flex-col items-center gap-2 text-muted-foreground">
              <Loader2 className="h-8 w-8 animate-spin text-primary" />
              <span className="text-xs">Загрузка документа...</span>
            </div>
          ) : loadError ? (
            <div className="text-center p-6 bg-background rounded-2xl border max-w-sm">
              <FileText className="mx-auto h-10 w-10 text-destructive mb-2" />
              <p className="font-semibold text-sm mb-1">Не удалось открыть документ</p>
              <p className="text-xs text-muted-foreground">
                Проверьте соединение с сервером или попробуйте открыть позже.
              </p>
            </div>
          ) : isPdf && blobUrl ? (
            <div className="w-full h-full flex items-center justify-center p-0">
              <iframe
                src={`${blobUrl}#toolbar=1&navpanes=0&scrollbar=1&view=FitH`}
                className="w-full h-full border-0 bg-white shadow-inner"
                title={doc.title}
              />
            </div>
          ) : isImage && blobUrl ? (
            <div className="overflow-auto w-full h-full flex items-start justify-center p-2">
              <img
                src={blobUrl}
                alt={doc.title}
                onDragStart={(e) => e.preventDefault()}
                style={{
                  transform: `scale(${zoomLevel / 100})`,
                  transformOrigin: "top center",
                  imageRendering: "-webkit-optimize-contrast",
                }}
                className="max-w-full rounded-md shadow-md transition-transform duration-150"
              />
            </div>
          ) : (
            <div className="text-center p-8 bg-background rounded-2xl border max-w-sm">
              <FileText className="mx-auto h-12 w-12 text-amber-500 mb-3" />
              <p className="font-semibold text-sm mb-1">Формат требует конвертации</p>
              <p className="text-xs text-muted-foreground">
                Файлы Word (.doc/.docx) не могут безопасно отображаться на мобильных без скачивания.
                Загрузите документ в формате <b>PDF</b> или <b>Фото</b>.
              </p>
            </div>
          )}
        </div>

        <div className="p-2.5 bg-secondary/60 border-t flex items-center justify-center gap-2 text-[11px] text-muted-foreground">
          <Lock size={12} className="text-amber-500" />
          <span>Режим «Только чтение». Загрузка документа жителям недоступна.</span>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog,DialogContent,DialogHeader,DialogTitle } from "@/components/ui/dialog";
import type { OfferWithMaster } from "@/lib/market/service";
import { CheckCircle2,Loader2,Phone,UserCheck } from "lucide-react";
import { useEffect,useState } from "react";

interface MarketOffersListModalProps {
  listingId: string;
  isOpen: boolean;
  onClose: () => void;
  onOfferAccepted?: () => void;
}

export function MarketOffersListModal({
  listingId,
  isOpen,
  onClose,
  onOfferAccepted,
}: MarketOffersListModalProps) {
  const [loading, setLoading] = useState(false);
  const [offers, setOffers] = useState<OfferWithMaster[]>([]);
  const [acceptingId, setAcceptingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fetchOffers = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/market/listings/${listingId}/offers`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Не удалось загрузить отклики");
      setOffers(data);
    } catch (caughtError) {
const err = caughtError instanceof Error ? caughtError : new Error(String(caughtError));

      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isOpen && listingId) {
      fetchOffers();
    }
  }, [isOpen, listingId]);

  const handleAccept = async (offerId: string) => {
    setAcceptingId(offerId);
    try {
      const res = await fetch(`/api/market/offers/${offerId}/accept`, {
        method: "POST",
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Ошибка при принятии отклика");

      await fetchOffers();
      onOfferAccepted?.();
    } catch (caughtError) {
const err = caughtError instanceof Error ? caughtError : new Error(String(caughtError));

      alert(err.message);
    } finally {
      setAcceptingId(null);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-lg rounded-2xl p-6">
        <DialogHeader>
          <div className="flex items-center gap-2">
            <UserCheck className="h-5 w-5 text-primary" />
            <DialogTitle className="text-base font-bold">
              Отклики мастеров на заявку
            </DialogTitle>
          </div>
        </DialogHeader>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-10 gap-2 text-muted-foreground">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="text-xs">Загрузка откликов...</span>
          </div>
        ) : error ? (
          <p className="text-xs text-destructive p-3">{error}</p>
        ) : offers.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-8">
            Откликов от мастеров пока нет.
          </p>
        ) : (
          <div className="space-y-3 pt-2 max-h-[60vh] overflow-y-auto pr-1">
            {offers.map((offer) => (
              <div
                key={offer.id}
                className={`p-4 rounded-xl border space-y-2.5 transition-all ${
                  offer.status === "ACCEPTED"
                    ? "border-emerald-500/50 bg-emerald-500/5"
                    : "border-border bg-card"
                }`}
              >
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2">
                    <div className="size-9 rounded-full bg-primary/10 text-primary font-bold text-xs flex items-center justify-center">
                      {offer.master.fullName[0]}
                    </div>
                    <div>
                      <h4 className="m-0 font-bold text-sm flex items-center gap-1">
                        {offer.master.fullName}
                        <CheckCircle2 size={14} className="text-primary" />
                      </h4>
                      <p className="m-0 text-[11px] text-muted-foreground">
                        {offer.master.city}
                      </p>
                    </div>
                  </div>

                  <div className="text-right">
                    {offer.price && (
                      <span className="font-bold text-sm text-primary block">
                        {Number(offer.price).toLocaleString("ru-RU")} ₸
                      </span>
                    )}
                    <Badge
                      variant={offer.status === "ACCEPTED" ? "default" : "secondary"}
                      className={`text-[10px] ${
                        offer.status === "ACCEPTED" ? "bg-emerald-600 text-white" : ""
                      }`}
                    >
                      {offer.status === "ACCEPTED" ? "Принят" : "Откликнулся"}
                    </Badge>
                  </div>
                </div>

                <p className="text-xs text-foreground bg-muted/30 p-2.5 rounded-lg whitespace-pre-wrap">
                  {offer.message}
                </p>

                {offer.status === "ACCEPTED" && offer.master.phone && (
                  <div className="flex items-center justify-between p-2.5 rounded-lg bg-emerald-500/10 text-xs">
                    <div>
                      <span className="text-[10px] uppercase font-semibold text-emerald-600 dark:text-emerald-400 block">
                        Телефон мастера:
                      </span>
                      <span className="font-bold text-sm">{offer.master.phone}</span>
                    </div>
                    <a
                      href={`tel:${offer.master.phone}`}
                      className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-emerald-600 text-white font-medium text-xs hover:bg-emerald-700"
                    >
                      <Phone size={13} /> Звонок
                    </a>
                  </div>
                )}

                {offer.status !== "ACCEPTED" && (
                  <div className="flex justify-end pt-1">
                    <Button
                      size="sm"
                      onClick={() => handleAccept(offer.id)}
                      disabled={acceptingId === offer.id}
                      className="rounded-xl text-xs gap-1"
                    >
                      {acceptingId === offer.id ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      ) : (
                        <CheckCircle2 className="h-3.5 w-3.5" />
                      )}
                      Принять отклик
                    </Button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card,CardContent } from "@/components/ui/card";
import { Dialog,DialogContent,DialogHeader,DialogTitle } from "@/components/ui/dialog";
import type { MasterWithPortfolio } from "@/lib/masters/service";
import type { RequestCategory } from "@prisma/client";
import { Briefcase,CheckCircle2,Image as ImageIcon,List,Map as MapIcon,MapPin,Phone,Star,Wrench } from "lucide-react";
import { useState } from "react";

const CATEGORY_LABELS: Record<RequestCategory, string> = {
  PLUMBING: "Сантехника",
  ELECTRICITY: "Электрика",
  ELEVATOR: "Лифт",
  CLEANING: "Уборка",
  OTHER: "Другое",
};

export function MasterCatalogView({ initialMasters }: { initialMasters: MasterWithPortfolio[] }) {
  const [masters, _setMasters] = useState<MasterWithPortfolio[]>(initialMasters);
  const [selectedCategory, setSelectedCategory] = useState<string>("ALL");
  const [selectedMaster, setSelectedMaster] = useState<MasterWithPortfolio | null>(null);
  const [viewMode, setViewMode] = useState<"grid" | "map">("grid");

  const filteredMasters = selectedCategory === "ALL"
    ? masters
    : masters.filter((m) => m.categories.includes(selectedCategory as RequestCategory));

  return (
    <div className="grid gap-6">
      {/* Шапка управления: Категории + Переключение Сетка/Карта */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        {/* Фильтр по категориям */}
        <div className="flex flex-wrap gap-2">
          <Button
            variant={selectedCategory === "ALL" ? "default" : "outline"}
            size="sm"
            onClick={() => setSelectedCategory("ALL")}
            className="rounded-full text-xs"
          >
            Все мастера ({masters.length})
          </Button>
          {Object.entries(CATEGORY_LABELS).map(([cat, label]) => (
            <Button
              key={cat}
              variant={selectedCategory === cat ? "default" : "outline"}
              size="sm"
              onClick={() => setSelectedCategory(cat)}
              className="rounded-full text-xs"
            >
              {label}
            </Button>
          ))}
        </div>

        {/* Переключатель вида */}
        <div className="flex items-center gap-1 rounded-full border border-border p-1 bg-background">
          <Button
            variant={viewMode === "grid" ? "default" : "ghost"}
            size="sm"
            onClick={() => setViewMode("grid")}
            className="rounded-full text-xs gap-1.5 h-8"
          >
            <List size={14} />
            Список
          </Button>
          <Button
            variant={viewMode === "map" ? "default" : "ghost"}
            size="sm"
            onClick={() => setViewMode("map")}
            className="rounded-full text-xs gap-1.5 h-8"
          >
            <MapIcon size={14} />
            На карте
          </Button>
        </div>
      </div>

      {/* Отображение: Карта мастеров */}
      {viewMode === "map" && (
        <Card className="rounded-2xl shadow-sm overflow-hidden border">
          <CardContent className="p-0 relative">
            <div className="h-[480px] w-full bg-muted/30 relative flex flex-col justify-between p-4 bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px] dark:[background-size:16px_16px]">

              {/* Верхний баннер карты */}
              <div className="z-10 flex items-center justify-between gap-2 bg-background/90 backdrop-blur p-3 rounded-xl border shadow-sm">
                <div className="flex items-center gap-2">
                  <MapPin className="h-5 w-5 text-primary animate-bounce" />
                  <span className="text-xs font-semibold">Карта мастеров города (Кокшетау)</span>
                </div>
                <Badge variant="secondary" className="text-[10px]">
                  {filteredMasters.length} на карте
                </Badge>
              </div>

              {/* Сетка гео-пинов мастеров */}
              <div className="relative flex-1 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3 p-2 overflow-y-auto max-h-[380px]">
                {filteredMasters.map((master, _idx) => (
                  <div
                    key={master.id}
                    onClick={() => setSelectedMaster(master)}
                    className="cursor-pointer bg-card hover:bg-accent border border-border/80 p-3 rounded-2xl shadow-sm transition-all hover:scale-[1.02] flex flex-col justify-between"
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex items-center gap-2">
                        <div className="size-8 rounded-full bg-primary/10 text-primary font-bold text-xs flex items-center justify-center shrink-0">
                          {master.fullName[0]}
                        </div>
                        <div>
                          <p className="m-0 font-bold text-xs line-clamp-1">{master.fullName}</p>
                          <p className="m-0 text-[10px] text-muted-foreground">{master.city}</p>
                        </div>
                      </div>
                      <Badge className="bg-amber-500/10 text-amber-600 border-none text-[10px] px-1.5 py-0.5 gap-1 shrink-0">
                        <Star size={10} className="fill-amber-500 text-amber-500" />
                        4.9
                      </Badge>
                    </div>

                    <div className="mt-2 flex items-center justify-between pt-2 border-t text-[11px] text-primary font-medium">
                      <span>{CATEGORY_LABELS[master.categories[0] ?? "OTHER"] || "Мастер"}</span>
                      <span>Подробнее ↗</span>
                    </div>
                  </div>
                ))}
              </div>

              {/* Нижний подвал карты */}
              <div className="z-10 bg-background/90 backdrop-blur p-2.5 rounded-xl border text-[11px] text-muted-foreground text-center">
                Выберите мастера на карте для просмотра фото работ и вызова
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Список мастеров */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {filteredMasters.map((master) => (
          <Card key={master.id} className="rounded-2xl shadow-sm overflow-hidden flex flex-col justify-between">
            <CardContent className="pt-6">
              <div className="flex items-start justify-between gap-3">
                <div className="flex items-center gap-3">
                  <div className="flex size-12 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary font-bold text-lg">
                    {master.fullName.split(" ").map((n) => n[0]).join("")}
                  </div>
                  <div>
                    <h3 className="m-0 font-bold text-base flex items-center gap-1.5">
                      {master.fullName}
                      <CheckCircle2 size={16} className="text-primary" />
                    </h3>
                    <p className="m-0 text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                      <MapPin size={12} /> {master.city}
                    </p>
                  </div>
                </div>
              </div>

              {/* Категории */}
              <div className="mt-4 flex flex-wrap gap-1">
                {master.categories.map((cat) => (
                  <Badge key={cat} variant="secondary" className="text-[11px] font-normal">
                    {CATEGORY_LABELS[cat] || cat}
                  </Badge>
                ))}
              </div>

              {/* Описание / О себе */}
              {master.bio && (
                <p className="mt-3 text-xs text-muted-foreground line-clamp-2">
                  {master.bio}
                </p>
              )}

              {/* Превью работ */}
              {master.portfolio.length > 0 && (
                <div className="mt-4 rounded-xl border border-border/60 bg-secondary/20 p-2.5">
                  <p className="m-0 text-xs font-semibold text-muted-foreground flex items-center gap-1 mb-2">
                    <ImageIcon size={13} /> Портфолио ({master.portfolio.length} работ)
                  </p>
                  <div className="flex gap-2 overflow-x-auto pb-1">
                    {master.portfolio.slice(0, 3).map((item) => (
                      <div
                        key={item.id}
                        className="relative size-14 shrink-0 rounded-lg overflow-hidden border border-border bg-muted flex items-center justify-center text-[10px] text-muted-foreground font-medium"
                      >
                        {item.photoUrls[0] ? (
                          <img src={item.photoUrls[0]} alt={item.title} className="size-full object-cover" />
                        ) : (
                          <Briefcase size={18} />
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CardContent>

            <div className="p-4 pt-0 flex gap-2">
              <Button
                variant="outline"
                size="sm"
                className="w-full rounded-xl text-xs"
                onClick={() => setSelectedMaster(master)}
              >
                Портфолио и контакты
              </Button>
            </div>
          </Card>
        ))}

        {filteredMasters.length === 0 && (
          <div className="col-span-full py-12 text-center text-muted-foreground">
            <Wrench className="mx-auto size-8 mb-2 opacity-40" />
            <p className="m-0 text-sm">В выбранной категории мастера пока не найдены</p>
          </div>
        )}
      </div>

