                  const _hasOffered = myOfferedListingIds.has(item.id);
                  const isSelected = activeMapPin === item.id;
                  const categoryName = (CATEGORY_LABELS[language] && CATEGORY_LABELS[language][item.category]) || item.category;

                  return (
                    <Card 
                      key={item.id} 
                      onClick={() => setActiveMapPin(item.id)}
                      className={`rounded-2xl transition-all cursor-pointer border ${
                        isSelected 
                          ? "border-emerald-500 ring-2 ring-emerald-500/20 bg-emerald-950/10 shadow-md" 
                          : "border-border/80 hover:border-border hover:shadow-sm"
                      }`}
                    >
                      <CardContent className="p-4 space-y-2.5">
                        <div className="flex items-start justify-between gap-2">
                          <Badge variant="outline" className="text-[10px] font-bold uppercase tracking-wider">
                            {categoryName}
                          </Badge>

                          <span className="text-sm font-black text-emerald-500">
                            {item.estimatedBudget ? `${item.estimatedBudget.toLocaleString("ru-RU")} ₸` : "По договорённости"}
                          </span>
                        </div>

                        <div>
                          <h4 className="m-0 font-bold text-sm text-foreground leading-snug">{item.title}</h4>
                          <p className="m-0 mt-1 text-xs text-muted-foreground line-clamp-2 leading-relaxed">
                            {item.description}
                          </p>
                        </div>

                        <div className="pt-1 flex items-center justify-between border-t border-border/40 text-[11px] text-muted-foreground">
                          <span className="flex items-center gap-1 font-semibold text-foreground">
                            <MapPin size={12} className="text-emerald-500" /> {item.buildingLabel}
                          </span>

                          <Button
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              setSelectedListing(item);
                            }}
                            className="h-7 px-3 rounded-xl text-xs font-bold gap-1 bg-emerald-600 hover:bg-emerald-500 text-white"
                          >
                            <Send size={11} /> {L.respond}
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            </div>
          ) : (
            /* ВИД СПИСКОМ */
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {filteredListings.map((item) => {
                const hasOffered = myOfferedListingIds.has(item.id);
                const categoryName = (CATEGORY_LABELS[language] && CATEGORY_LABELS[language][item.category]) || item.category;

                return (
                  <Card key={item.id} className="rounded-3xl shadow-sm border border-border/80 overflow-hidden flex flex-col justify-between hover:shadow-md transition-shadow">
                    <CardContent className="pt-5 space-y-3">
                      <div className="flex items-start justify-between gap-2">
                        <Badge variant="secondary" className="text-[10px] font-bold uppercase">
                          {categoryName}
                        </Badge>
                        <span className="text-sm font-black text-emerald-500">
                          {item.estimatedBudget ? `${item.estimatedBudget.toLocaleString("ru-RU")} ₸` : "Договорная"}
                        </span>
                      </div>

                      <div>
                        <h4 className="m-0 font-bold text-base text-foreground leading-tight">{item.title}</h4>
                        <p className="m-0 mt-1.5 text-xs text-muted-foreground line-clamp-3 leading-relaxed">
                          {item.description}
                        </p>
                      </div>

                      <div className="flex items-center gap-1 text-xs font-semibold text-muted-foreground">
                        <MapPin size={13} className="text-emerald-500 shrink-0" />
                        <span className="truncate">{item.buildingLabel}</span>
                      </div>
                    </CardContent>

                    <div className="p-4 pt-0">
                      {hasOffered ? (
                        <Button variant="outline" disabled className="w-full rounded-2xl text-xs gap-1.5 h-10">
                          <CheckCircle2 size={14} className="text-emerald-500" /> {L.youOffered}
                        </Button>
                      ) : (
                        <Button
                          onClick={() => setSelectedListing(item)}
                          className="w-full rounded-2xl text-xs font-bold gap-1.5 h-10 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md shadow-emerald-500/20"
                        >
                          <Send size={13} /> {L.respond}
                        </Button>
                      )}
                    </div>
                  </Card>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* ВКЛАДКА 2: ВОРК-ПОРТФОЛИО МАСТЕРА С ФОТО ДО/ПОСЛЕ, ВИДЕО И ЛАЙКАМИ */}
      {activeTab === "portfolio" && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="m-0 text-base font-bold text-foreground flex items-center gap-2">
                <Sparkles size={16} className="text-amber-500" />
                {language === "kk" ? "Орындалған жұмыстар есебі (Дейін / Кейін + Видео)" : language === "en" ? "Completed Work Reports (Before/After + Video)" : "Отчеты работ (До / После + Видео)"}
              </h3>
              <p className="m-0 text-xs text-muted-foreground">
                {language === "kk" ? "Тұрғындар мен төрағалар жұмыс нәтижесін көріп, лайк пен баға қоя алады" : language === "en" ? "Residents can review, rate, and like completed job media" : "Жители дома ставят оценки как в Kaspi и могут лайкать результат"}
              </p>
            </div>
            <Button 
              size="sm" 
              onClick={() => setIsAddReportOpen(true)}
              className="rounded-xl text-xs font-bold gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white"
            >
              <Camera size={13} />
              {language === "kk" ? "+ Жаңа есеп қосу" : language === "en" ? "+ Add Report" : "+ Добавить отчет До/После"}
            </Button>
          </div>

          <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {currentPortfolioItems.map((item, idx) => {
              const isLiked = userLiked[idx];
              const likes = likesCount[idx] || 0;
              const stats = ratingStats[idx] || { stars: 5.0, totalVotes: 10 };

              return (
                <Card key={idx} className="rounded-3xl border border-border/80 overflow-hidden shadow-sm hover:shadow-md transition-shadow flex flex-col justify-between">
                  {/* Блок слайдера фото ДО и ПОСЛЕ */}
                  <div className="relative h-44 bg-muted overflow-hidden">
                    <div className="grid grid-cols-2 h-full">
                      <div className="relative bg-slate-900 border-r border-background/50 flex flex-col justify-between p-2.5">
                        <span className="px-2 py-0.5 rounded-md bg-rose-500/90 text-white font-black text-[10px] uppercase tracking-wider self-start shadow-sm">
                          {language === "kk" ? "Дейін" : language === "en" ? "Before" : "До"}
                        </span>
                        <div className="text-center text-muted-foreground">
                          <Wrench size={24} className="mx-auto opacity-50 mb-1" />
                          <span className="text-[10px]">Аварийное состояние</span>
                        </div>
                        <span />
                      </div>
                      <div className="relative bg-emerald-950/60 flex flex-col justify-between p-2.5">
                        <span className="px-2 py-0.5 rounded-md bg-emerald-500/90 text-white font-black text-[10px] uppercase tracking-wider self-start shadow-sm">
                          {language === "kk" ? "Кейін" : language === "en" ? "After" : "После"}
                        </span>
                        <div className="text-center text-emerald-400">
                          <CheckCircle2 size={24} className="mx-auto opacity-80 mb-1" />
                          <span className="text-[10px] font-bold">100% Устранено</span>
                        </div>
                        <span />
                      </div>
                    </div>

                    {/* Бейдж видеоотчета */}
                    <Badge className="absolute bottom-2 right-2 bg-black/80 text-white border border-white/20 text-[10px] font-bold gap-1 backdrop-blur-md">
                      🎬 Видео 0:15
                    </Badge>
                  </div>

                  <CardContent className="p-4 space-y-3">
                    <div>
                      <div className="flex items-center justify-between gap-1">
                        <span className="text-[10px] font-bold text-emerald-500 uppercase tracking-wider">{item.category}</span>

                        {/* Рейтинг как в Kaspi / Яндекс */}
                        <div className="flex items-center gap-1 bg-amber-500/10 px-2 py-0.5 rounded-lg border border-amber-500/20">
                          <Star size={12} className="fill-amber-500 text-amber-500" />
                          <span className="text-xs font-black text-amber-500">{stats.stars.toFixed(1)}</span>
                          <span className="text-[10px] text-muted-foreground">({stats.totalVotes})</span>
                        </div>
                      </div>

                      <h4 className="m-0 font-bold text-sm text-foreground mt-1 leading-snug">{item.title}</h4>
                      <p className="m-0 mt-1 text-xs text-muted-foreground leading-relaxed">{item.description}</p>
                    </div>

                    {/* Подвал карточки с лайками и гарантией */}
                    <div className="pt-2.5 border-t border-border/40 flex items-center justify-between text-xs">
                      <span className="text-muted-foreground flex items-center gap-1 text-[11px] font-medium">
                        <MapPin size={11} className="text-emerald-500" /> {item.address}
                      </span>

                      <button
                        onClick={() => handleToggleLike(idx)}
                        className={`flex items-center gap-1.5 px-2.5 py-1 rounded-xl font-bold text-xs transition-all ${
                          isLiked 
                            ? "bg-rose-500/15 text-rose-500 border border-rose-500/30 scale-105" 
                            : "bg-muted text-muted-foreground hover:bg-muted/80 hover:text-foreground"
                        }`}
                      >
                        ❤️ <span>{likes}</span>
                      </button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {/* ВКЛАДКА 3: МОИ ОТКЛИКИ */}
      {activeTab === "myOffers" && (
        <div className="grid gap-3.5 sm:grid-cols-2">
          {myOffers.map((offer) => (
            <Card key={offer.id} className="rounded-2xl shadow-sm p-4 space-y-2.5 border border-border/80">
              <div className="flex items-start justify-between gap-2">
                <h4 className="m-0 font-bold text-sm text-foreground">
                  {offer.listing?.title || "Заказ закрыт"}
                </h4>
                <Badge
                  variant={offer.status === "ACCEPTED" ? "default" : "secondary"}
                  className={`text-[10px] font-bold ${
                    offer.status === "ACCEPTED"
                      ? "bg-emerald-600 text-white shadow-sm"
                      : offer.status === "DECLINED"
                      ? "bg-destructive/10 text-destructive"
                      : ""
                  }`}
                >
                  {offer.status === "ACCEPTED"
                    ? "✓ Принят председателем"
                    : offer.status === "DECLINED"
                    ? "Отклонён"
                    : "Ожидает ответа"}
                </Badge>
              </div>

              {offer.listing?.buildingLabel && (
                <p className="m-0 text-xs text-muted-foreground flex items-center gap-1 font-medium">
                  <MapPin size={12} className="text-emerald-500" /> {offer.listing.buildingLabel}
                </p>
              )}

              <p className="m-0 text-xs bg-muted/40 p-3 rounded-xl whitespace-pre-wrap text-foreground/90 border border-border/40">
                {offer.message}
              </p>

              <div className="flex items-center justify-between pt-1">
                {offer.price ? (
                  <span className="text-xs font-black text-emerald-500">
                    Предложение: {Number(offer.price).toLocaleString("ru-RU")} ₸
                  </span>
                ) : <span />}

                {offer.status === "ACCEPTED" && (
                  <Button size="sm" className="h-7 px-3 rounded-xl text-xs font-bold gap-1 bg-emerald-600 text-white">
                    <Phone size={11} /> Связаться
                  </Button>
                )}
              </div>
            </Card>
          ))}

          {myOffers.length === 0 && (
            <div className="col-span-full py-16 text-center text-muted-foreground rounded-3xl border border-dashed border-border p-8 bg-card/40">
              <Store size={28} className="mx-auto mb-2 text-muted-foreground/60" />
              <p className="m-0 font-bold text-sm text-foreground">Вы ещё не откликались на заказы</p>
              <p className="m-0 mt-1 text-xs text-muted-foreground">
                Перейдите на вкладку «Заказы города» и выберите заявку на карте
              </p>
            </div>
          )}
        </div>
      )}

      {/* МОДАЛКА ОТПРАВКИ ОТКЛИКА */}
      <Dialog open={Boolean(selectedListing)} onOpenChange={(open) => !open && setSelectedListing(null)}>
        <DialogContent className="max-w-md rounded-3xl p-6 border border-border bg-card shadow-2xl">
          {selectedListing && (
            <>
              <DialogHeader>
                <div className="flex items-center gap-2 mb-1">
                  <Badge variant="outline" className="text-[10px] font-bold uppercase">
                    {CATEGORY_LABELS[language]?.[selectedListing.category] || selectedListing.category}
                  </Badge>
                  <span className="text-xs text-muted-foreground flex items-center gap-1">
                    <MapPin size={11} className="text-emerald-500" /> {selectedListing.buildingLabel}
                  </span>
                </div>
                <DialogTitle className="text-base font-bold text-foreground">
                  {selectedListing.title}
                </DialogTitle>
              </DialogHeader>

              <form onSubmit={handleSendOffer} className="space-y-4 pt-2">
                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-foreground">
                    Ваше предложение и сроки выезда
                  </label>
                  <textarea
                    className="w-full rounded-2xl border border-border bg-background p-3 text-sm outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all text-foreground"
                    rows={3}
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="Например: Готов выехать сегодня в течение 30 минут со всем инструментом. Официальная гарантия 30 дней."
                    required
                  />
                </div>

                <div>
                  <label className="mb-1.5 block text-xs font-semibold text-foreground">
                    Ориентировочная стоимость (₸)
                  </label>
                  <input
                    type="number"
                    className="w-full rounded-2xl border border-border bg-background p-3 text-sm outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all text-foreground font-semibold"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    placeholder={selectedListing.estimatedBudget ? `Рекомендуемый бюджет: ${selectedListing.estimatedBudget}` : "Например: 15000"}
                  />
                </div>

                {error && <p className="text-xs text-destructive font-medium">{error}</p>}

                <div className="flex justify-end gap-2 pt-2">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setSelectedListing(null)}
                    className="rounded-2xl text-xs font-semibold"
                  >
                    Отмена
                  </Button>
                  <Button 
                    type="submit" 
                    disabled={submitting} 
                    className="rounded-2xl text-xs font-bold gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md shadow-emerald-500/25"
                  >
                    {submitting ? "Отправка..." : "Отправить отклик"}
                  </Button>
                </div>
              </form>
            </>
          )}
        </DialogContent>
      </Dialog>

      {/* МОДАЛКА РЕДАКТИРОВАНИЯ ДАННЫХ И ФОТОГРАФИИ МАСТЕРА */}
      <Dialog open={isEditProfileOpen} onOpenChange={setIsEditProfileOpen}>
        <DialogContent className="max-w-md rounded-3xl p-6 border border-border bg-card shadow-2xl">
          <DialogHeader>
            <DialogTitle className="text-base font-bold text-foreground flex items-center gap-2">
              <User size={18} className="text-emerald-500" />
              {L.editProfile}
            </DialogTitle>
          </DialogHeader>

          <form onSubmit={handleSaveProfile} className="space-y-4 pt-2">
            {/* Фото профиля мастера */}
            <div className="flex flex-col items-center justify-center p-4 rounded-2xl bg-muted/30 border border-dashed border-border/80 text-center gap-3">
              <div className="relative group cursor-pointer">
                {avatarUrl ? (
                  <img 
                    src={avatarUrl} 
                    alt="Master photo" 
                    className="size-20 rounded-2xl object-cover border-2 border-emerald-500 shadow-md"
                  />
                ) : (
                  <div className="size-20 rounded-2xl bg-gradient-to-br from-emerald-500 to-emerald-700 flex items-center justify-center text-3xl font-black text-white shadow-md">
                    {fullName.charAt(0).toUpperCase()}
                  </div>
                )}
                <label 
                  htmlFor="avatar-upload" 
                  className="absolute inset-0 bg-black/60 rounded-2xl opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center text-white transition-opacity cursor-pointer text-[10px] font-bold gap-1"
                >
                  <Camera size={18} />
                  <span>Сменить</span>
                </label>
              </div>

              <div>
                <label 
                  htmlFor="avatar-upload" 
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-background border border-border text-xs font-semibold cursor-pointer hover:bg-muted transition-colors text-foreground"
                >
                  <UploadCloud size={13} className="text-emerald-500" />
                  {L.uploadPhoto}
                </label>
                <input 
                  id="avatar-upload" 
                  type="file" 
                  accept="image/*" 
                  onChange={handleAvatarUpload} 
                  className="hidden" 
                />
                <p className="m-0 mt-1 text-[11px] text-muted-foreground">
                  JPG, PNG до 5 МБ. Фото будет видно председателям при отклике.
                </p>
              </div>
            </div>

            {/* Поле имени мастера */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-foreground">
                ФИО или название бригады
              </label>
              <input
                type="text"
                className="w-full rounded-2xl border border-border bg-background p-3 text-sm outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all text-foreground font-semibold"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                placeholder="Например: Александр Новокрещенов"
                required
              />
            </div>

            {/* Город и радиус выезда */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-foreground">
                Основной город и адрес базирования
              </label>
              <div className="flex items-center gap-2 p-2.5 rounded-2xl bg-muted/40 border border-border/60 text-xs text-muted-foreground font-medium">
                <MapPin size={14} className="text-emerald-500 shrink-0" />
                <span>{city}, район ул. Мира, 68</span>
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsEditProfileOpen(false)}
                className="rounded-2xl text-xs font-semibold"
              >
                Отмена
              </Button>
              <Button 
                type="submit" 
                disabled={savingProfile} 
                className="rounded-2xl text-xs font-bold gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md shadow-emerald-500/25"
              >
                {savingProfile ? "Сохранение..." : L.save}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>

      {/* МОДАЛКА ДОБАВЛЕНИЯ ОТЧЕТА С ФОТО ДО/ПОСЛЕ И ВИДЕО */}
      <Dialog open={isAddReportOpen} onOpenChange={setIsAddReportOpen}>
        <DialogContent className="max-w-md rounded-3xl p-6 border border-border bg-card shadow-2xl">
          <DialogHeader>
            <DialogTitle className="text-base font-bold text-foreground flex items-center gap-2">
              <Camera size={18} className="text-emerald-500" />
              {language === "kk" ? "Жұмыс есебін жариялау" : language === "en" ? "Publish Work Report" : "Публикация отчета о работе"}
            </DialogTitle>
          </DialogHeader>

          <form 
            onSubmit={(e) => {
              e.preventDefault();
              setIsAddReportOpen(false);
            }} 
            className="space-y-4 pt-2"
          >
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-foreground">
                {language === "kk" ? "Жұмыс атауы" : language === "en" ? "Job Title" : "Название выполненной работы"}
              </label>
              <input
                type="text"
                className="w-full rounded-2xl border border-border bg-background p-3 text-sm outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 transition-all text-foreground font-semibold"
                value={reportTitle}
                onChange={(e) => setReportTitle(e.target.value)}
                placeholder="Например: Замена стояка ГВС и установка счетчиков"
                required
              />
            </div>

            {/* Загрузка фото ДО и ПОСЛЕ */}
            <div className="grid grid-cols-2 gap-3">
              <div className="p-3 rounded-2xl bg-rose-500/5 border border-dashed border-rose-500/30 text-center">
                <span className="block text-[11px] font-black text-rose-500 mb-1">ФОТО «ДО»</span>
                <label className="cursor-pointer text-xs font-bold text-foreground inline-flex items-center gap-1">
                  <UploadCloud size={13} className="text-rose-500" /> Прикрепить
                  <input type="file" accept="image/*" className="hidden" />
                </label>
              </div>

              <div className="p-3 rounded-2xl bg-emerald-500/5 border border-dashed border-emerald-500/30 text-center">
                <span className="block text-[11px] font-black text-emerald-500 mb-1">ФОТО «ПОСЛЕ»</span>
                <label className="cursor-pointer text-xs font-bold text-foreground inline-flex items-center gap-1">
                  <UploadCloud size={13} className="text-emerald-500" /> Прикрепить
                  <input type="file" accept="image/*" className="hidden" />
                </label>
              </div>
            </div>

            {/* Загрузка видео */}
            <div className="p-3.5 rounded-2xl bg-muted/40 border border-border flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="size-8 rounded-xl bg-primary/10 text-primary flex items-center justify-center font-bold">
                  🎬
                </div>
                <div>
                  <span className="block text-xs font-bold text-foreground">Видео процесса (до 30 сек)</span>
                  <span className="text-[10px] text-muted-foreground">Для жителей и подтверждения отчета</span>
                </div>
              </div>
              <label className="cursor-pointer px-3 py-1.5 rounded-xl bg-background border border-border text-xs font-semibold hover:bg-muted text-foreground">
                Выбрать
                <input type="file" accept="video/*" className="hidden" />
              </label>
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsAddReportOpen(false)}
                className="rounded-2xl text-xs font-semibold"
              >
                Отмена
              </Button>
              <Button 
                type="submit" 
                className="rounded-2xl text-xs font-bold gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md shadow-emerald-500/25"
              >
                {language === "kk" ? "Есепті сақтау" : language === "en" ? "Save Report" : "Опубликовать отчет"}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
